WITH RankedMovies AS ( SELECT mt.id AS movie_id, mt.title AS movie_title, mt.production_year, COUNT(DISTINCT ci.person_id) AS total_actors, ARRAY_AGG(DISTINCT an.name) AS actor_names FROM aka_title mt JOIN complete_cast cc ON mt.id = cc.movie_id JOIN cast_info ci ON cc.subject_id = ci.id JOIN aka_name an ON ci.person_id = an.person_id WHERE mt.production_year >= 2000 GROUP BY mt.id, mt.title, mt.production_year ), PopularKeywords AS ( SELECT mk.movie_id, k.keyword, COUNT(mk.keyword_id) AS keyword_count FROM movie_keyword mk JOIN keyword k ON mk.keyword_id = k.id GROUP BY mk.movie_id, k.keyword HAVING COUNT(mk.keyword_id) > 1 ), CompanyDetails AS ( SELECT mc.movie_id, co.name AS company_name, ct.kind AS company_type FROM movie_companies mc JOIN company_name co ON mc.company_id = co.id JOIN company_type ct ON mc.company_type_id = ct.id ) SELECT rm.movie_id, rm.movie_title, rm.production_year, rm.total_actors, rm.actor_names, pk.keyword, cd.company_name, cd.company_type FROM RankedMovies rm LEFT JOIN PopularKeywords pk ON rm.movie_id = pk.movie_id LEFT JOIN CompanyDetails cd ON rm.movie_id = cd.movie_id ORDER BY rm.production_year DESC, rm.total_actors DESC LIMIT 100;

