WITH ranked_movies AS ( SELECT t.id AS movie_id, t.title, t.production_year, COUNT(DISTINCT c.person_id) AS cast_count, STRING_AGG(DISTINCT ak.name, ', ') AS aka_names, ROW_NUMBER() OVER (PARTITION BY t.production_year ORDER BY COUNT(DISTINCT c.person_id) DESC) AS rank FROM aka_title AS t JOIN complete_cast AS cc ON t.id = cc.movie_id JOIN cast_info AS c ON cc.subject_id = c.id JOIN aka_name AS ak ON c.person_id = ak.person_id GROUP BY t.id, t.title, t.production_year ), top_movies AS ( SELECT rm.* FROM ranked_movies rm WHERE rm.rank <= 5 ) SELECT tm.movie_id, tm.title, tm.production_year, tm.cast_count, tm.aka_names, ci.kind AS company_type, cn.name AS company_name FROM top_movies tm JOIN movie_companies mc ON tm.movie_id = mc.movie_id JOIN company_name cn ON mc.company_id = cn.id JOIN company_type ci ON mc.company_type_id = ci.id ORDER BY tm.production_year DESC, tm.cast_count DESC;

