omer_sk = cd.cd_demo_sk WHERE (r.total_store_returned_quantity > 0 OR r.total_web_returned_quantity > 0) AND r.total_return_amount IS NOT NULL AND (cd.cd_gender = 'F' OR cd.cd_gender IS NULL) ORDER BY r.total_return_amount DESC LIMIT 100;

