WITH CustomerInfo AS ( SELECT c.c_customer_sk, CONCAT(TRIM(c.c_first_name), ' ', TRIM(c.c_last_name)) AS customer_full_name, cd.cd_gender, cd.cd_marital_status, cd.cd_education_status, cd.cd_purchase_estimate FROM customer c JOIN customer_demographics cd ON c.c_current_cdemo_sk = cd.cd_demo_sk ), AddressInfo AS ( SELECT ca.ca_address_sk, CONCAT(TRIM(ca.ca_street_number), ' ', TRIM(ca.ca_street_name), ' ', TRIM(ca.ca_street_type), CASE WHEN ca.ca_suite_number IS NOT NULL AND ca.ca_suite_number <> '' THEN CONCAT(', Suite ', TRIM(ca.ca_suite_number)) ELSE '' END) AS full_address, ca.ca_city, ca.ca_state, ca.ca_zip, ca.ca_country FROM customer_address ca ), SalesData AS ( SELECT ws.ws_bill_customer_sk, SUM(ws.ws_net_paid_inc_tax) AS total_sales, COUNT(ws.ws_order_number) AS total_orders FROM web_sales ws GROUP BY ws.ws_bill_customer_sk ) SELECT ci.customer_full_name, ci.cd_gender, ci.cd_marital_status, ci.cd_education_status, ai.full_address, ai.ca_city, ai.ca_state, ai.ca_zip, ai.ca_country, COALESCE(sd.total_sales, 0) AS total_sales, COALESCE(sd.total_orders, 0) AS total_orders FROM CustomerInfo ci JOIN AddressInfo ai ON ci.c_customer_sk = ai.ca_address_sk LEFT JOIN SalesData sd ON ci.c_customer_sk = sd.ws_bill_customer_sk WHERE ci.cd_gender = 'M' AND ci.cd_marital_status = 'S' ORDER BY total_sales DESC LIMIT 50;

