WITH customer_info AS ( SELECT c.c_customer_sk, CONCAT(c.c_first_name, ' ', c.c_last_name) AS full_name, cd.cd_gender, cd.cd_marital_status, cd.cd_education_status, ca.ca_city, ca.ca_state, ca.ca_zip FROM customer c JOIN customer_demographics cd ON c.c_current_cdemo_sk = cd.cd_demo_sk JOIN customer_address ca ON c.c_current_addr_sk = ca.ca_address_sk ), sales_data AS ( SELECT ws.ws_bill_customer_sk, SUM(ws.ws_ext_sales_price) AS total_sales, COUNT(DISTINCT ws.ws_order_number) AS total_orders FROM web_sales ws GROUP BY ws.ws_bill_customer_sk ), merged_data AS ( SELECT ci.c_customer_sk, ci.full_name, ci.cd_gender, ci.cd_marital_status, ci.cd_education_status, ci.ca_city, ci.ca_state, ci.ca_zip, COALESCE(sd.total_sales, 0) AS total_sales, COALESCE(sd.total_orders, 0) AS total_orders FROM customer_info ci LEFT JOIN sales_data sd ON ci.c_customer_sk = sd.ws_bill_customer_sk ) SELECT *, CASE WHEN total_sales = 0 THEN 'No Sales' WHEN total_sales < 100 THEN 'Low Sales' WHEN total_sales BETWEEN 100 AND 500 THEN 'Medium Sales' ELSE 'High Sales' END AS sales_category, UPPER(full_name) AS upper_full_name, LENGTH(full_name) AS name_length, SUBSTR(full_name, 1, 5) AS name_start FROM merged_data WHERE ca_city LIKE 'San%' ORDER BY total_sales DESC;

